benchmark.source:
component BenchCell(size: Float64) {
    body {
        Row(gap: 1) {
            Shape(width: size, height: 3, shape: Rounded(1), fill: "#356EAF")

        }
    }
}
component BenchRow(size: Float64) {
    body {
        Row(gap: 3) {
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
            BenchCell(size: size)
        }
    }
}
app ColumnBench {
    state tileWidth: Float64 = 8.0
    body {
        Column(gap: 3) {
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        BenchRow(size: tileWidth)
        }
    }
}

